types-and-variables.cpp

// 类型示例：展示基础类型、初始化、赋值、作用域和 auto。
#include &lt;iostream&gt;
#include &lt;string&gt;

int main() {
  int age = 18;
  double scale = 1.5;
  bool ready = true;
  char grade = 'A';
  std::string name = "Ada";

  age = 19;
  const auto score = 95.5;

  {
    int localValue = 7;
    std::cout &lt;&lt; "局部变量: " &lt;&lt; localValue &lt;&lt; "\n";
  }

  std::cout &lt;&lt; name &lt;&lt; " 的年龄是 " &lt;&lt; age &lt;&lt; "\n";
  std::cout &lt;&lt; "缩放: " &lt;&lt; scale &lt;&lt; "\n";
  std::cout &lt;&lt; "是否就绪: " &lt;&lt; ready &lt;&lt; "\n";
  std::cout &lt;&lt; "等级: " &lt;&lt; grade &lt;&lt; "\n";
  std::cout &lt;&lt; "分数: " &lt;&lt; score &lt;&lt; "\n";
  return 0;
}

初始化与赋值
初始化是在创建变量时给它第一个值：


初始化

int age = 18;
double scale = 1.5;
bool ready = true;
char grade = 'A';
std::string name = "Ada";

赋值是修改变量当前保存的值：


赋值

age = 19;

= 在这里表示赋值，不是数学中的“恒等”。变量只有在类型允许时才能赋入新值。

作用域决定名字能用多久
变量从声明处开始生效，到它所在的代码块结束。花括号 {} 会形成一个作用域：


局部作用域

{
  int localValue = 7;
  std::cout &lt;&lt; localValue &lt;&lt; "\n";
}

离开花括号后，localValue 不能再使用。把变量的生命周期限制在需要的范围内，代码更容易阅读。

constants.cpp

// 常量示例：展示命名常量、初始化要求和不可修改限制。
#include &lt;iostream&gt;

int main() {
  const int kMaxRetries = 3;
  constexpr double kPi = 3.14159;

  std::cout &lt;&lt; "最大重试次数: " &lt;&lt; kMaxRetries &lt;&lt; "\n";
  std::cout &lt;&lt; "圆周率近似值: " &lt;&lt; kPi &lt;&lt; "\n";
  return 0;
}

命名与可读性
常量名使用项目约定的大驼峰并在前面加 k，例如 kMaxRetries。名字描述用途，不把单位、范围和实现细节塞进一个过长的名称。


常量命名

const int kMaxRetries = 3;
const double kInitialScale = 1.0;
